"""Presentation-only main tables, using verified full-precision computation exports."""
from pathlib import Path
from decimal import Decimal, ROUND_HALF_UP
import csv
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'paper/writing_sample_generated'
TABLES=ROOT/'data/v4/writing_sample/tables'
PAIR=ROOT/'data/v4/round2/closeout/closeout_2026-11-10/paired'
OUT.mkdir(exist_ok=True)
ledger=[]
def rows(p):
    with p.open() as f:return list(csv.DictReader(f))
def key4(r):return r['clock'],r['analysis'],r['variant'],r['statistic']
def n(x,d=0):return f'{float(x):,.{d}f}'
def ci(lo,hi,d=0):return r'\ensuremath{['+n(lo,d).replace(',','{,}')+r',\,'+n(hi,d).replace(',','{,}')+']}'
def out(name,lines):(OUT/name).write_text('% Generated by writing_sample_core_tables.py.\n'+'\n'.join(lines)+'\n')
def source_record(table,label,clock,estimate,lo,hi,source):
    ledger.append(dict(table=table,label=label,clock=clock,estimate=estimate,ci_low=lo,ci_high=hi,source=source))
def lower_share(p):
    k=round(float(p)*2001-1)
    assert abs(float(p)-(k+1)/2001)<1e-10
    return str((Decimal(2000-k)*100/Decimal(2000)).quantize(Decimal('.1'),rounding=ROUND_HALF_UP))
paired={(r['clock'],r['scale'],r['term']):r for r in rows(PAIR/'paired_summary.csv')}
points={(r['clock'],r['scale']):r for r in rows(PAIR/'point_statistics.csv')}
influence={(r['clock'],r['specification']):r for r in rows(ROOT/'data/v4/round2/closeout/closeout_2026-11-10/influence/specification_statistics.csv')}
d={(r['clock'],r['benchmark']):r for r in rows(TABLES/'table3_persistence_both_benchmarks.csv')}
# households and purchases quoted in the headings, in Panel A and in the notes of Tables 3 and 4
assert [(int(float(d[(c,'event_study')]['households'])),int(float(d[(c,'event_study')]['purchases']))) for c in ('T','P')]==[(38,7964),(30,6095)]
cont={r['sample']:r for r in rows(TABLES/'S1_continuation_purchases.csv') if r['scale']=='raw' and r['subset']=='all' and r['regression']=='Y0_on_x'}
assert (int(float(cont['cohort']['households'])),int(float(cont['cohort']['observations'])),int(float(cont['all_purchases']['households'])))==(38,7964,232)
assert {int(float(r['formation_dates'])) for r in rows(TABLES/'S1_continuation_formation_grid.csv')}=={139}
assert [int(r['n']) for r in rows(ROOT/'data/v4/ext/ledger_households.csv') if r['clock']=='T' and r['stage']=='purchases_default' and r['reason']=='households_with_any_purchase_2015_2025']==[233]
shifted={}
lines=[r'\small\setlength{\tabcolsep}{3.5pt}',r'\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}>{\raggedright\arraybackslash}p{3.0cm}cS[table-format=-4.0]S[table-format=4.0]c@{}}',r'\toprule',r'Benchmark & \shortstack{Slope\\(SE)} & {\shortstack{Covariance\\($\mathrm{bp}^2$)}} & {\shortstack{SE\\($\mathrm{bp}^2$)}} & \shortstack{95\% bootstrap\\interval ($\mathrm{bp}^2$)} \\',r'\midrule']
for clock,heading in [('T','Trade date: 38 households; 7,964 purchases'),('P','Disclosure date: 30 households; 6,095 purchases')]:
    lines.append(r'\multicolumn{5}{l}{\textit{'+heading+r'}} \\')
    for benchmark,label in [('factor_only','Factor-only'),('event_study','Event-study'),('event_study_minus_factor_only','Benchmark gap'),('market_adjusted',r'Market-adjusted\textsuperscript{*}')]:
        r=d[clock,benchmark]
        if benchmark=='event_study_minus_factor_only':slope=r'\textemdash';se=r['covariance_se_paired_bootstrap']
        else:
            se=r['covariance_se_two_way']
            if benchmark=='market_adjusted':
                z=influence[clock,'market_adjusted'];sv=float(z['slope']);ss=float(se)/float(z['var_a_bp2'])
            else:sv=float(r['slope']);ss=float(r['slope_se_conditional_two_way'])
            slope=rf'\ensuremath{{{sv:.2f}}} ({ss:.2f})'
            below_count=round(float(r['placebo_share_below_pct'])*20)
            assert abs(float(r['placebo_share_below_pct'])-below_count/20)<1e-8
            shifted[clock,benchmark]=str((Decimal(below_count)*100/Decimal(2000)).quantize(Decimal('.1'),rounding=ROUND_HALF_UP))
        lines.append(' & '.join([label,slope,n(r['covariance']),n(se),ci(r['boot_low'],r['boot_high'])])+r' \\')
        source_record('Table3',benchmark,clock,r['covariance'],r['boot_low'],r['boot_high'],'data/v4/writing_sample/tables/table3_persistence_both_benchmarks.csv')
    if clock=='T':lines.append(r'\addlinespace')
lines.extend([r'\bottomrule',r'\end{tabular*}']);out('table03_persistence.tex',lines)

levels={r['outcome']:r for r in rows(TABLES/'table4_panelA_levels.csv')}
forecasts=[r for r in rows(TABLES/'S1_continuation_purchases.csv') if r['scale']=='raw' and r['subset']=='all' and r['regression']=='Y0_on_x']
grid=next(r for r in rows(TABLES/'S1_continuation_formation_grid.csv') if r['scale']=='raw' and r['subset']=='all')
assert abs(float(levels['charge_bp']['mean_bp'])-float(levels['alpha20_bp']['mean_bp'])-float(levels['compounding_bp']['mean_bp']))<1e-8
lines=[r'\begin{table}[H]',r'\centering\begin{threeparttable}',r'\caption{The alpha charge and subsequent returns, 2015--2025}\label{tab:alpha-levels}',r'\small\setlength{\tabcolsep}{5pt}',r'\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}lS[table-format=-2.1]S[table-format=2.1]@{}}',r'\toprule',r'\multicolumn{3}{l}{\textit{Panel A: Mean levels on 7,964 purchases (bp)}} \\',r'Quantity & {Mean} & {SE} \\',r'\midrule']
for outcome,label in [('charge_bp',r'Alpha charge ($A=Y^0-Y^1$)'),('alpha20_bp',r'\quad Of which: $20\times$ recent alpha'),('compounding_bp',r'\quad Of which: compounding'),('Y0_bp','Factor-only return'),('Y1_bp','Event-study return')]:
    r=levels[outcome];lines.append(' & '.join([label,n(r['mean_bp'],1),n(r['se_two_way_bp'],1)])+r' \\')
    source_record('Table4A',outcome,'T',r['mean_bp'],r['ci_low_bp'],r['ci_high_bp'],'data/v4/writing_sample/tables/table4_panelA_levels.csv')
lines.extend([r'\bottomrule',r'\end{tabular*}',r'\vspace{0.6em}',r'\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}>{\raggedright\arraybackslash}p{4.1cm}c c c r@{}}',r'\toprule',r'\multicolumn{5}{l}{\textit{Panel B: Prediction from recent alpha}} \\',r'Sample & \shortstack{Forecast coefficient\\(SE)} & 95\% interval & $p(\lambda=1)$ & Observations \\',r'\midrule'])
for sample,label in [('cohort','Persistence sample'),('all_purchases','All trade-date purchases'),('grid','Fixed-date traded stocks')]:
    r=grid if sample=='grid' else next(z for z in forecasts if z['sample']==sample)
    coeff=rf"\ensuremath{{{float(r['estimate']):.3f}}} ({float(r['se']):.3f})"
    p_one=r'$<0.001$' if float(r['p_one'])<.001 else f"{float(r['p_one']):.3f}"
    lines.append(' & '.join([label,coeff,ci(r['ci_low'],r['ci_high'],3),p_one,n(r['observations'])])+r' \\')
    source_record('Table4B',sample,'T',r['estimate'],r['ci_low'],r['ci_high'],'data/v4/writing_sample/tables/S1_continuation_'+('formation_grid' if sample=='grid' else 'purchases')+'.csv')
lines.extend([r'\bottomrule',r'\end{tabular*}',r'\begin{tablenotes}[flushleft]\footnotesize\raggedright',r'\item \textit{Notes:} Panel A reports means in bp for the 38-household persistence sample, weighting each purchase equally. The alpha charge equals 20 times recent alpha plus the compounding remainder. Panel B regresses factor-only returns on 20 times recent alpha, both in bp. Both panels use unwinsorized returns, charges, and predictors. The all-purchase regression covers 232 of the 233 households with trade-date purchases, as the remaining household has no purchase with both an estimable benchmark and complete 20-day returns. Purchase regressions include fixed effects for 20-day entry blocks. Standard errors in these regressions and in Panel A are clustered by household and entry block. For the fixed-date sample of stocks traded by congressional households during the study period, I average cross-sectional slopes over 139 dates spaced 20 trading days apart and use a three-lag Newey--West standard error. Intervals are 95\%, and tests of $\lambda=1$ are two-sided. See Appendix~\ref{app:continuation} for alternative transformations and size subsets and Appendix~\ref{app:continuation-placebos} for comparisons of return levels at actual and shifted dates.',r'\end{tablenotes}\end{threeparttable}',r'\end{table}'])
out('table04_levels.tex',lines)

decomp={key4(r):r for r in rows(ROOT/'data/v4/ext/decomposition.csv')}
lines=[r'\footnotesize\setlength{\tabcolsep}{3pt}',r'\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}>{\raggedright\arraybackslash}p{5.6cm}S[table-format=-4.0]cS[table-format=-4.0]c@{}}',r'\toprule',r'& \multicolumn{2}{c}{Trade date} & \multicolumn{2}{c}{Disclosure date} \\',r'\cmidrule(lr){2-3}\cmidrule(lr){4-5}',r'Component & {Estimate} & 95\% interval & {Estimate} & 95\% interval \\',r'\midrule']
components=[('K00',r'Factor-only persistence $K(Y^{0w},Y^{0w})$','base'),('KDD',r'Charge covariance $+K(A^w,A^w)$','adj'),('K0D',r'Early factor-only return, late charge $-K(Y^{0w},A^w)$','cross_base_adj'),('KD0',r'Early charge, late factor-only return $-K(A^w,Y^{0w})$','cross_adj_base'),('K11',r'Event-study persistence $K(Y^{1w},Y^{1w})$','total')]
for term,label,pname in components:
    if term=='K11':lines.append(r'\midrule')
    r=paired['T','winsorized',term];q=paired['P','winsorized',term]
    shifted['T',term]=lower_share(decomp['T','decomposition','no_alpha_omit',f'placebo_{pname}_wins']['placebo_p'])
    lines.append(' & '.join([label,n(r['estimate']),ci(r['ci_low'],r['ci_high']),n(q['estimate']),ci(q['ci_low'],q['ci_high'])])+r' \\')
    for clock,z in [('T',r),('P',q)]:source_record('Table5',term,clock,z['estimate'],z['ci_low'],z['ci_high'],'paired_summary.csv')
lines.extend([r'\bottomrule',r'\end{tabular*}']);out('table05_decomposition.tex',lines)

# Appendix table: shifted-date ranks of the statistics in Tables 2 and 4
assert (shifted['T','K00'],shifted['T','K11'])==(shifted['T','factor_only'],shifted['T','event_study'])
lines=[r'\small\setlength{\tabcolsep}{4pt}',r'\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}lS[table-format=3.1]S[table-format=3.1]@{}}',r'\toprule',r'Statistic & {Trade date} & {Disclosure date} \\',r'\midrule',
       r'\multicolumn{3}{l}{\textit{Persistence covariances (Table~\ref{tab:tau})}} \\']
for benchmark,label in [('factor_only','Factor-only'),('event_study','Event-study'),('market_adjusted','Market-adjusted')]:
    lines.append(' & '.join([label,shifted['T',benchmark],shifted['P',benchmark]])+r' \\')
lines+=[r'\addlinespace',r'\multicolumn{3}{l}{\textit{Components of event-study persistence (Table~\ref{tab:benchmark-decomposition})}} \\']
for term,label,_ in components[1:4]:
    lines.append(' & '.join([label,shifted['T',term],r'{\textemdash}'])+r' \\')
lines.extend([r'\bottomrule',r'\end{tabular*}']);out('appendix_shifted_dates.tex',lines)

overlap={key4(r):r for r in rows(ROOT/'data/v4/ext/overlap_exclusion.csv')}
extended={key4(r):r for r in rows(ROOT/'data/v4/final/decomposition_corrected.csv')}
lines=[r'\small\setlength{\tabcolsep}{5pt}',r'\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}lS[table-format=2.0]S[table-format=-4.0]S[table-format=-4.0]S[table-format=-4.0]S[table-format=4.0]@{}}',r'\toprule',r'Specification & \multicolumn{1}{c}{Households} & \multicolumn{1}{c}{Factor-only} & \multicolumn{1}{c}{Event-study} & \multicolumn{1}{c}{\shortstack{Benchmark\\gap}} & \multicolumn{1}{c}{\shortstack{Charge\\covariance}} \\',r'\midrule']
for clock,heading in [('T','Trade date'),('P','Disclosure date')]:
    lines.append(r'\multicolumn{6}{l}{\textit{'+heading+r'}} \\')
    for label,variant in [('Baseline','winsorized'),('Unwinsorized','raw'),('Same-stock exclusion','own_overlap'),('Calendar exclusion','calendar_overlap'),('Extended sample','extended')]:
        if variant in ['winsorized','raw']:
            p=points[clock,variant]
            total,alternative,recurrence=map(float,[p['K11'],p['K00'],p['KDD']])
            households=38 if clock=='T' else 30
            src='point_statistics.csv'
        elif variant=='extended':
            def get(stat): return extended[clock,'decomposition_corrected','corrected|no_alpha_omit',stat]
            total,alternative,recurrence=[float(get(stat)['value']) for stat in ['tau2_total_wins','tau2_base_wins','tau2_adj_wins']]
            households=int(get('tau2_total_wins')['n_households'])
            src='data/v4/final/decomposition_corrected.csv'
        else:
            def get(stat): return overlap[clock,'overlap_exclusion',variant,stat]
            total,alternative,recurrence=[float(get(stat)['value']) for stat in ['tau2_headline_restricted','tau2_no_alpha_restricted','term_adj_wins_restricted']]
            households=int(get('tau2_headline_restricted')['n_households'])
            src='data/v4/ext/overlap_exclusion.csv'
        lines.append(' & '.join([label,str(households),n(alternative),n(total),n(total-alternative),n(recurrence)])+r' \\')
        for term,value in [('K00',alternative),('K11',total),('gap',total-alternative),('KDD',recurrence)]: source_record('robustness',label+':'+term,clock,value,'','',src)
    if clock=='T':lines.append(r'\addlinespace')
lines.extend([r'\bottomrule',r'\end{tabular*}'])
(OUT/'table06_robustness.tex').write_text('\n'.join(lines)+'\n')


with (OUT/'core_table_provenance.csv').open('w') as f:
    w=csv.DictWriter(f,fieldnames=list(ledger[0]));w.writeheader();w.writerows(ledger)
